import 'package:flutter/material.dart'; import '../../services/auth_service.dart'; import '../../widgets/custom_button.dart'; import '../../widgets/custom_text_field.dart'; import '../student/student_home_page.dart'; class RegisterPage extends StatefulWidget { const RegisterPage({super.key}); @override State<RegisterPage> createState()=>_RegisterPageState(); } class _RegisterPageState extends State<RegisterPage>{ final name=TextEditingController(),email=TextEditingController(),password=TextEditingController(); bool busy=false; Future<void> register() async {setState(()=>busy=true);try{await AuthService().register(name:name.text.trim(),email:email.text.trim(),password:password.text);if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const StudentHomePage()),(_)=>false);}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تعذر إنشاء الحساب')));}finally{if(mounted)setState(()=>busy=false);}} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تسجيل طالب')),body:ListView(padding:const EdgeInsets.all(20),children:[CustomTextField(controller:name,label:'اسم الطالب'),CustomTextField(controller:email,label:'البريد الإلكتروني'),CustomTextField(controller:password,label:'كلمة المرور',obscure:true),const SizedBox(height:12),CustomButton(label:busy?'جارٍ التسجيل...':'تسجيل',onPressed:busy?null:register)])); }